package dev.ayaz.november30;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.time.*;import java.util.*;
public class MainActivity extends Activity {
 final int BG=0xff0b0e13,CARD=0xff171c25,GOLD=0xffffd43b,WHITE=0xfff5f6fa,MUTED=0xffa0a7b5,GREEN=0xff50d6a2;
 final String[] habits={"Walk your daily step target","Sleep 7–8 hours","Workout / planned recovery","Avoid junk food","No phone for 30 min after waking","Read 10 pages","Track today's expenses","Study Terraform / AWS","No phone during meals","Meditate 10–15 minutes","Clean your workspace","Write 3 priorities","Write 3 gratitudes"};
 final String[] icons={"🚶","🌙","💪","🥗","📵","📖","₹","💻","🍽","🧘","✨","🎯","♥"};
 SharedPreferences prefs; LinearLayout root,content;int day;
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("nov30",MODE_PRIVATE);LocalDate now=LocalDate.now();day=now.getYear()==2026&&now.getMonthValue()==11?now.getDayOfMonth():1;render();}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void add(LinearLayout p,View v,int bottom){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(bottom);p.addView(v,lp);}
 void render(){root=col();root.setBackgroundColor(BG);setContentView(root);LinearLayout header=col();pad(header,22,22,22,14);add(header,text("NOVEMBER // 30",25,GOLD,true),3);add(header,text("BUILD YOUR BETTER SELF  •  2026",11,MUTED,true),0);root.addView(header);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));content=col();pad(content,18,8,18,30);sc.addView(content);dashboard();calendar();habitsUI();expense();journal();footer();}
 void dashboard(){int count=count(day),total=0,active=0;for(int d=1;d<=30;d++){int c=count(d);total+=c;if(c>0)active++;}LinearLayout card=col();card.setBackground(shape(CARD,20));pad(card,20,20,20,18);add(card,text("DAY "+String.format(Locale.US,"%02d",day)+"  /  30",13,GOLD,true),10);add(card,text(count+" / 13",42,WHITE,true),2);add(card,text("Today's habits completed",13,MUTED,false),12);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(13);bar.setProgress(count);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(GOLD));add(card,bar,16);add(card,text("MONTHLY SCORE   "+total+" / 390     •     "+Math.round(total*100f/390)+"%",13,WHITE,true),8);add(card,text("ACTIVE DAYS   "+active+"     •     CURRENT STREAK   "+streak()+" days",12,MUTED,false),0);add(content,card,22);add(content,text("YOUR NOVEMBER",18,WHITE,true),12);add(content,text("Tap a day to review or update it.",12,MUTED,false),12);}
 void calendar(){LinearLayout card=col();card.setBackground(shape(CARD,18));pad(card,10,14,10,14);LinearLayout week=row();for(String n:new String[]{"S","M","T","W","T","F","S"}){TextView t=text(n,12,MUTED,true);t.setGravity(Gravity.CENTER);week.addView(t,new LinearLayout.LayoutParams(0,dp(26),1));}add(card,week,5);for(int w=0;w<5;w++){LinearLayout r=row();for(int x=0;x<7;x++){final int d=w*7+x+1;TextView t=text(d<=30?""+d:"",14,d==day?BG:WHITE,d==day);t.setGravity(Gravity.CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));r.addView(t,lp);if(d<=30){int c=count(d);t.setBackground(shape(d==day?GOLD:c==13?GREEN:c>=9?0xff315e50:c>0?0xff3e4531:0xff242a35,11));t.setOnClickListener(v->{day=d;render();});}}add(card,r,0);}add(content,card,22);}
 String target(){if(day<=7)return "6,000 steps • 3 workouts this week • 30 min study";if(day<=14)return "8,000 steps • 4 workouts this week • 45 min study";return "10,000 steps • 4–5 workouts this week • 45 min study";}
 void habitsUI(){add(content,text("DAILY CHECKLIST",18,WHITE,true),5);add(content,text("WEEK "+((day-1)/7+1)+" TARGET  •  "+target(),12,GOLD,false),13);for(int i=0;i<habits.length;i++){final int ix=i;LinearLayout r=row();r.setBackground(shape(CARD,13));pad(r,14,10,12,10);TextView label=text(icons[i]+"  "+habits[i],14,WHITE,false);r.addView(label,new LinearLayout.LayoutParams(0,-2,1));CheckBox cb=new CheckBox(this);cb.setButtonTintList(android.content.res.ColorStateList.valueOf(GOLD));cb.setChecked(prefs.getBoolean("h"+day+"_"+i,false));r.addView(cb);r.setOnClickListener(v->cb.setChecked(!cb.isChecked()));cb.setOnCheckedChangeListener((button,checked)->{prefs.edit().putBoolean("h"+day+"_"+ix,checked).apply();render();});add(content,r,7);}add(content,text("Recovery days count when you follow your planned rest.",11,MUTED,false),20);}
 void expense(){add(content,text("EXPENSE LEDGER",18,WHITE,true),12);LinearLayout card=col();card.setBackground(shape(CARD,16));pad(card,16,15,16,15);long total=0;for(int d=1;d<=30;d++)total+=prefs.getLong("expense"+d,0);add(card,text("November recorded: ₹"+total,16,GOLD,true),10);EditText amount=new EditText(this);amount.setSingleLine(true);amount.setInputType(2);amount.setText(prefs.getLong("expense"+day,0)==0?"":String.valueOf(prefs.getLong("expense"+day,0)));amount.setHint("Today's spending (₹)");amount.setHintTextColor(MUTED);amount.setTextColor(WHITE);add(card,amount,8);Button save=new Button(this);save.setText("SAVE EXPENSE");save.setTextColor(BG);save.setBackgroundTintList(android.content.res.ColorStateList.valueOf(GOLD));save.setOnClickListener(v->{try{long value=Long.parseLong(amount.getText().toString().trim());if(value<0)throw new Exception();prefs.edit().putLong("expense"+day,value).apply();render();}catch(Exception e){Toast.makeText(this,"Enter a valid whole rupee amount",Toast.LENGTH_SHORT).show();}});add(card,save,0);add(content,card,22);}
 void journal(){add(content,text("DAILY REFLECTION",18,WHITE,true),12);LinearLayout card=col();card.setBackground(shape(CARD,16));pad(card,16,15,16,15);EditText notes=new EditText(this);notes.setMinLines(4);notes.setGravity(Gravity.TOP);notes.setTextColor(WHITE);notes.setHintTextColor(MUTED);notes.setHint("3 priorities, 3 gratitudes, and a quick reflection…");notes.setText(prefs.getString("notes"+day,""));add(card,notes,10);Button save=new Button(this);save.setText("SAVE JOURNAL");save.setTextColor(BG);save.setBackgroundTintList(android.content.res.ColorStateList.valueOf(GOLD));save.setOnClickListener(v->{prefs.edit().putString("notes"+day,notes.getText().toString()).apply();Toast.makeText(this,"Reflection saved",Toast.LENGTH_SHORT).show();});add(card,save,0);add(content,card,18);}
 void footer(){add(content,text("30 DAYS • 13 HABITS • 390 POSSIBLE POINTS",12,GOLD,true),6);add(content,text("80% success = 312 points. One missed day is not failure.\nYour data stays on this device.",12,MUTED,false),0);}
 int count(int d){int c=0;for(int i=0;i<13;i++)if(prefs.getBoolean("h"+d+"_"+i,false))c++;return c;}int streak(){int s=0;int d=day;while(d>=1&&count(d)>=9){s++;d--;}return s;}
}